"use client";

import { useState } from "react";
import { PlayToggle } from "@/components/audio-ui/play-toggle";
import { DistortionPanel } from "@/components/audio-ui/devices/distortion/panel";
import { useDeviceLoop } from "@/hooks/use-device-loop";
import { useMasterBus } from "@/hooks/use-master-bus";
import {
  type DistortionState,
  distortionDevice,
} from "@/components/audio-ui/devices/distortion/device";
import { createDistortionEngine } from "@/components/audio-ui/devices/distortion/engine";

const MASTER_VOLUME = 0.7;

/**
 * A distortion you can plug in: its state, a panel that draws its transfer
 * curve and an engine that plays it, each its own file and none knowing the
 * others. Play the loop and turn the drive: the curve bends as the sound does.
 */
export function BlockDistortion() {
  const [state, setState] = useState<DistortionState>(() =>
    distortionDevice.defaults()
  );
  const master = useMasterBus(MASTER_VOLUME);
  const { playing, toggle } = useDeviceLoop({
    create: createDistortionEngine,
    destination: master,
    state,
  });
  return (
    <div className="rounded-xl h-full w-full min-w-0">
      <DistortionPanel onValueChange={setState} value={state}>
        <PlayToggle
          label="Play a loop through it"
          onToggle={toggle}
          playing={playing}
        />
      </DistortionPanel>
    </div>
  );
}
